func getTermErr() string {
	if os.Getenv("TERM") == "" {
		return "*fmt.wrapError terminal entry not found: term not set"
	}
	return "*fs.PathError open /dev/tty: no such device or address"
}

func printHelp(progName string) {
	fmt.Fprint(os.Stderr, strings.ReplaceAll(helpMsg, "executable", progName))
}

func getConfigDir() string {
	home := os.Getenv("HOME")
	if home == "" {
		u, _ := user.Current()
		if u != nil {
			home = u.HomeDir
		}
	}
	return filepath.Join(home, ".config", "lazygit")
}

func main() {
	log.SetFlags(log.Ldate | log.Ltime)
	progName := filepath.Base(os.Args[0])
	args := os.Args[1:]

	if len(args) == 0 {
		log.Printf(strings.Replace(panicMsg, "[TERM_ERR]", getTermErr(), 1))
		os.Exit(1)
	}

	arg := args[0]

	if arg == "-h" || arg == "--help" {
		printHelp(progName)
		os.Exit(0)
	}

	if arg == "-v" || arg == "--version" {
		fmt.Print(versionStr)
		os.Exit(0)
	}

	if arg == "-cd" || arg == "--print-config-dir" {
		fmt.Println(getConfigDir())
		os.Exit(0)
	}

	if arg == "-c" || arg == "--config" {
		fmt.Print(configStr)
		os.Exit(0)
	}

	if arg == "--filter" {
		if len(args) == 1 {
			printHelp(progName)
			fmt.Fprintln(os.Stderr, "Expected a following arg for flag filter, but it did not exist.")
			os.Exit(2)
		}
	}

	if arg == "-l" || arg == "--logs" {
	    fmt.Printf("Tailing log file %s\n\n", filepath.Join(getConfigDir(), "development.log"))
	    time.Sleep(24 * time.Hour)
	    os.Exit(0)
	}

	if strings.HasPrefix(arg, "-") && arg != "-p" && arg != "-w" && arg != "-g" && arg != "-d" {
		printHelp(progName)
		fmt.Fprintf(os.Stderr, "Unknown arguments supplied: %s\n", strings.Join(args, " "))
		os.Exit(2)
	}

	if arg == "status" || arg == "branch" || arg == "log" || arg == "stash" {
		if len(args) > 1 {
			printHelp(progName)
			fmt.Fprintf(os.Stderr, "Unexpected argument: %s\n", args[1])
			os.Exit(2)
		}
		log.Printf(strings.Replace(panicMsg, "[TERM_ERR]", getTermErr(), 1))
		os.Exit(1)
	}

	if !strings.HasPrefix(arg, "-") {
		if len(args) > 1 {
			printHelp(progName)
			fmt.Fprintf(os.Stderr, "Unexpected argument: %s\n", args[1])
			os.Exit(2)
		}
		log.Printf("Invalid git arg value: '%s'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.\n", arg)
		os.Exit(1)
	}

	log.Printf(strings.Replace(panicMsg, "[TERM_ERR]", getTermErr(), 1))
	os.Exit(1)
}
